public static string IntToBinaryString(int number)
{
const int mask = 1;
var binary = string.Empty;
while (number > 0)
{
// Logical AND the number and prepend it to the result string
binary = (number & mask) + binary;
number = number >> 1;
}
return binary;
}
// '>>' Operator
